package com.trader.qa;

import java.io.File;
import java.nio.file.Files;
import java.nio.charset.StandardCharsets;
import java.text.Normalizer;
import java.util.regex.Pattern;
import org.apache.pdfbox.Loader;
import org.apache.pdfbox.text.PDFTextStripper;
import org.junit.Test;
import static org.junit.Assert.*;

/** Reads only PDFs generated by the real Android instrumentation fixture; never synthesizes PDFs. */
public class InvoicePdfContentTest {
    private File fixture(String name) {
        File f=new File(System.getProperty("pdf.fixture.dir"),name);
        assertTrue("Missing real Android-generated fixture: "+f,f.isFile());
        return f;
    }
    @Test public void generatedPdfContainsInvoiceIdentityArabicAndFinancialTotal() throws Exception {
        File file=fixture("invoice-content.pdf");
        assertEquals("%PDF-",new String(Files.readAllBytes(file.toPath()),0,5,StandardCharsets.US_ASCII));
        try (var pdf=Loader.loadPDF(file)) {
            assertEquals(1,pdf.getNumberOfPages());
            String text=Normalizer.normalize(new PDFTextStripper().getText(pdf),Normalizer.Form.NFKC);
            assertTrue(text.contains("INV-000008"));
            assertTrue(text.contains("100.00"));
            assertTrue("Arabic text must survive real PDF generation/extraction",Pattern.compile("[\\u0600-\\u06ff]").matcher(text).find());
        }
    }
    @Test public void longInvoicePaginatesWithoutDroppingFinalItemOrTotal() throws Exception {
        try (var pdf=Loader.loadPDF(fixture("invoice-long.pdf"))) {
            assertTrue(pdf.getNumberOfPages()>1);
            String text=new PDFTextStripper().getText(pdf);
            assertTrue(text.contains("ITEM-099"));
            assertTrue(text.contains("100.00"));
        }
    }
    @Test public void customerStatementPreservesPaidDebtTotalsAndBothTransactionIdentities() throws Exception {
        try (var pdf=Loader.loadPDF(fixture("customer-statement.pdf"))) {
            assertEquals(1,pdf.getNumberOfPages());
            String text=Normalizer.normalize(new PDFTextStripper().getText(pdf),Normalizer.Form.NFKC);
            for (String expected:new String[]{"CUSTOMER-STATEMENT","#201","#202","20.25","30.50","50.75"})
                assertTrue("Missing statement content: "+expected,text.contains(expected));
        }
    }
    @Test public void monthlyReportPreservesFinancialSummaryAndFinalDayAcrossPages() throws Exception {
        try (var pdf=Loader.loadPDF(fixture("monthly-report.pdf"))) {
            assertTrue(pdf.getNumberOfPages()>1);
            String text=Normalizer.normalize(new PDFTextStripper().getText(pdf),Normalizer.Form.NFKC);
            for (String expected:new String[]{"MONTHLY-STORE","12345.67","2345.67","700.00","900.00","1000.00","777.25","444.50"})
                assertTrue("Missing monthly report content: "+expected,text.contains(expected));
            assertTrue("Arabic report headings must survive extraction",Pattern.compile("[\\u0600-\\u06ff]").matcher(text).find());
        }
    }


    @Test public void viewModelInvoicePreservesRefundNetAmountAndDerivedCustomerBalances() throws Exception {
        try (var pdf=Loader.loadPDF(fixture("invoice-return-viewmodel.pdf"))) {
            assertTrue(pdf.getNumberOfPages()>=1);
            String text=Normalizer.normalize(new PDFTextStripper().getText(pdf),Normalizer.Form.NFKC);
            for (String expected:new String[]{"INV-000009","RETURN-ITEM","RETURN-CUSTOMER","VM-RETURN-END","100.00","25.00","75.00","10.00","85.00"})
                assertTrue("Missing actual partial-return invoice content: "+expected,text.contains(expected));
            // PDF text extraction can reverse the glyph order of mixed RTL currency/numbers.
            String refund="(?:-\\h*₪\\h*25\\.00|-\\h*25\\.00\\h*₪|₪\\h*-\\h*25\\.00|₪\\h*25\\.00\\h*-|25\\.00\\h*-\\h*₪|25\\.00\\h*₪\\h*-)";
            assertTrue("Refund25 must be a currency deduction; extracted text: "+text,Pattern.compile(refund).matcher(text).find());
        }
    }
}
